#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
int main(void) {
    char text[101],*end; if(scanf("%100s",text)!=1)return 1;
    errno=0;long value=strtol(text,&end,10);
    if(errno==ERANGE || end==text || *end!='\0' || value < -1000 || value > 1000)puts("ОШИБКА");
    else printf("%ld\n",value);
    return 0;
}
